const fs = require('fs');

const [n, t] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let dp = new Map();

for (let a = 1; a <= 4; a++) {
    for (let b = 1; b <= 4; b++) {
        if (a === b) continue;
        const dir = b > a ? 1 : -1;
        dp.set(`${b},${dir},0,0`, 1n);
    }
}

for (let i = 3; i <= n; i++) {
    const next = new Map();

    for (const [key, count] of dp) {
        const [last, dir, peaks, valleys] = key.split(',').map(Number);

        for (let value = 1; value <= 4; value++) {
            if (value === last) continue;

            const newDir = value > last ? 1 : -1;
            let newPeaks = peaks;
            let newValleys = valleys;

            if (dir === 1 && newDir === -1) newPeaks++;
            if (dir === -1 && newDir === 1) newValleys++;

            if (newPeaks > t || newValleys > t - 1) continue;

            const newKey = `${value},${newDir},${newPeaks},${newValleys}`;
            next.set(newKey, (next.get(newKey) || 0n) + count);
        }
    }

    dp = next;
}

let answer = 0n;

for (const [key, count] of dp) {
    const [, , peaks, valleys] = key.split(',').map(Number);
    if (peaks === t && valleys === t - 1) answer += count;
}

