const fs = require('fs');

const [n, t] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const valleys = t;
const size = (t + 1) * valleys * 4 * 2;

function index(peaks, mins, last, dir) {
    return (((peaks * valleys + mins) * 4 + last) * 2 + dir);
}

let dp = new Float64Array(size);

for (let a = 0; a < 4; a++) {
    for (let b = 0; b < 4; b++) {
        if (a === b) continue;
        const dir = b > a ? 0 : 1;
        dp[index(0, 0, b, dir)]++;
    }
}

for (let length = 2; length < n; length++) {
    const next = new Float64Array(size);

    for (let peaks = 0; peaks <= t; peaks++) {
        for (let mins = 0; mins < valleys; mins++) {
            for (let last = 0; last < 4; last++) {
                for (let dir = 0; dir < 2; dir++) {
                    const count = dp[index(peaks, mins, last, dir)];
                    if (count === 0) continue;

                    for (let current = 0; current < 4; current++) {
                        if (current === last) continue;

                        const newDir = current > last ? 0 : 1;
                        let newPeaks = peaks;
                        let newMins = mins;

                        if (dir === 0 && newDir === 1) newPeaks++;
                        if (dir === 1 && newDir === 0) newMins++;

                        if (newPeaks <= t && newMins < valleys) {
                            next[index(newPeaks, newMins, current, newDir)] += count;
                        }
                    }
                }
            }
        }
    }

    dp = next;
}

let answer = 0;
for (let last = 0; last < 4; last++) {
    for (let dir = 0; dir < 2; dir++) {
        answer += dp[index(t, t - 1, last, dir)];
    }
}

console.log(answer.toString());

const fs = require('fs');

const [n, t] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const valleysNeeded = t - 1;
const V = t;
const P = t + 1;
const size = 4 * 2 * P * V;

const index = (last, dir, peaks, valleys) =>
    (((last * 2 + dir) * P + peaks) * V + valleys);

let dp = new Float64Array(size);

for (let first = 0; first < 4; first++) {
    for (let second = 0; second < 4; second++) {
        if (first === second) continue;
        const dir = second > first ? 1 : 0;
        dp[index(second, dir, 0, 0)]++;
    }
}

for (let length = 2; length < n; length++) {
    const nextDp = new Float64Array(size);

    for (let last = 0; last < 4; last++) {
        for (let dir = 0; dir < 2; dir++) {
            for (let peaks = 0; peaks <= t; peaks++) {
                for (let valleys = 0; valleys <= valleysNeeded; valleys++) {
                    const count = dp[index(last, dir, peaks, valleys)];
                    if (count === 0) continue;

                    for (let next = 0; next < 4; next++) {
                        if (next === last) continue;

                        const nextDir = next > last ? 1 : 0;
                        let newPeaks = peaks;
                        let newValleys = valleys;

                        if (dir === 1 && nextDir === 0) newPeaks++;
                        if (dir === 0 && nextDir === 1) newValleys++;

                        if (newPeaks <= t && newValleys <= valleysNeeded) {
                            nextDp[index(next, nextDir, newPeaks, newValleys)] += count;
                        }
                    }
                }
            }
        }
    }

    dp = nextDp;
}

let answer = 0;
for (let last = 0; last < 4; last++) {
    for (let dir = 0; dir < 2; dir++) {
        answer += dp[index(last, dir, t, valleysNeeded)];
    }
}

console.log(answer.toString());
